CREATE TABLE IF NOT EXISTS business (id BINARY(16) PRIMARY KEY, user_id BINARY(16) NOT NULL, `name` VARCHAR(512) NOT NULL, description VARCHAR(1024) NOT NULL, address VARCHAR(512) NOT NULL, latitude DOUBLE PRECISION NULL, longitude DOUBLE PRECISION NULL, currency VARCHAR(3) NOT NULL, timezone VARCHAR(255) NOT NULL, working_days TINYINT DEFAULT 62 NOT NULL, instagram VARCHAR(255) NULL, telegram VARCHAR(255) NULL, viber VARCHAR(255) NULL, whatsapp VARCHAR(255) NULL, phone VARCHAR(255) NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL);
ALTER TABLE business ADD CONSTRAINT business_user_id_unique UNIQUE (user_id);
CREATE TABLE IF NOT EXISTS business_working_hours (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, business_id BINARY(16) NOT NULL, day_of_week TINYINT NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, CONSTRAINT fk_business_working_hours_business_id__id FOREIGN KEY (business_id) REFERENCES business(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX business_working_hours_business_id ON business_working_hours (business_id);
CREATE TABLE IF NOT EXISTS business_day_offs (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, business_id BINARY(16) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, CONSTRAINT fk_business_day_offs_business_id__id FOREIGN KEY (business_id) REFERENCES business(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX business_day_offs_business_id ON business_day_offs (business_id);
CREATE INDEX business_day_offs_business_id_start_date ON business_day_offs (business_id, start_date);
CREATE TABLE IF NOT EXISTS business_dashboard (id BINARY(16) PRIMARY KEY, user_id BINARY(16) NOT NULL, business_id BINARY(16) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_business_dashboard_business_id__id FOREIGN KEY (business_id) REFERENCES business(id) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE business_dashboard ADD CONSTRAINT business_dashboard_user_id_unique UNIQUE (user_id);
CREATE INDEX business_dashboard_business_id ON business_dashboard (business_id);
CREATE TABLE IF NOT EXISTS client (id BINARY(16) PRIMARY KEY, business_id BINARY(16) NOT NULL, `name` VARCHAR(512) NOT NULL, lastname VARCHAR(512) NOT NULL, phone VARCHAR(512) NOT NULL, email VARCHAR(512) NOT NULL, user_id BINARY(16) NULL, source_updated_at TIMESTAMP(6) NULL, CONSTRAINT fk_client_business_id__id FOREIGN KEY (business_id) REFERENCES business(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX client_business_id ON client (business_id);
CREATE INDEX client_phone ON client (phone);
CREATE INDEX client_email ON client (email);
CREATE INDEX client_user_id ON client (user_id);
CREATE TABLE IF NOT EXISTS business_permissions (id BINARY(16) PRIMARY KEY, user_id BINARY(16) NOT NULL, business_id BINARY(16) NOT NULL, permission INT NOT NULL, CONSTRAINT fk_business_permissions_business_id__id FOREIGN KEY (business_id) REFERENCES business(id) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE business_permissions ADD CONSTRAINT business_permissions_user_id_business_id_unique UNIQUE (user_id, business_id);
CREATE TABLE IF NOT EXISTS service_group (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, business_id BINARY(16) NOT NULL, `name` VARCHAR(512) NOT NULL, CONSTRAINT fk_service_group_business_id__id FOREIGN KEY (business_id) REFERENCES business(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX service_group_business_id ON service_group (business_id);
ALTER TABLE service_group ADD CONSTRAINT service_group_business_id_name_unique UNIQUE (business_id, `name`);
CREATE TABLE IF NOT EXISTS service (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, business_id BINARY(16) NOT NULL, group_id BINARY(16) NOT NULL, `name` VARCHAR(512) NOT NULL, duration INT NOT NULL, price_currency VARCHAR(3) NOT NULL, price_unscaled BIGINT NOT NULL, price_scale INT NOT NULL, available BOOLEAN DEFAULT TRUE NOT NULL, CONSTRAINT fk_service_business_id__id FOREIGN KEY (business_id) REFERENCES business(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_service_group_id__id FOREIGN KEY (group_id) REFERENCES service_group(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX service_business_id ON service (business_id);
CREATE INDEX service_group_id ON service (group_id);
ALTER TABLE service ADD CONSTRAINT service_business_id_group_id_name_unique UNIQUE (business_id, group_id, `name`);
CREATE TABLE IF NOT EXISTS employee (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, business_id BINARY(16) NOT NULL, `name` VARCHAR(512) NOT NULL, lastname VARCHAR(512) NOT NULL, phone VARCHAR(512) NULL, email VARCHAR(512) NULL, user_id BINARY(16) NOT NULL, source_updated_at TIMESTAMP(6) NULL, CONSTRAINT fk_employee_business_id__id FOREIGN KEY (business_id) REFERENCES business(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX employee_business_id ON employee (business_id);
CREATE INDEX employee_phone ON employee (phone);
CREATE INDEX employee_email ON employee (email);
CREATE INDEX employee_user_id ON employee (user_id);
CREATE TABLE IF NOT EXISTS employee_can_provide_service (id BINARY(16) PRIMARY KEY, employee_id BINARY(16) NOT NULL, service_id BINARY(16) NOT NULL, business_id BINARY(16) NOT NULL, CONSTRAINT fk_employee_can_provide_service_employee_id__id FOREIGN KEY (employee_id) REFERENCES employee(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_employee_can_provide_service_service_id__id FOREIGN KEY (service_id) REFERENCES service(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_employee_can_provide_service_business_id__id FOREIGN KEY (business_id) REFERENCES business(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX employee_can_provide_service_service_id ON employee_can_provide_service (service_id);
CREATE INDEX employee_can_provide_service_business_id ON employee_can_provide_service (business_id);
ALTER TABLE employee_can_provide_service ADD CONSTRAINT employee_can_provide_service_employee_id_service_id_unique UNIQUE (employee_id, service_id);
CREATE TABLE IF NOT EXISTS employee_invitation (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, business_id BINARY(16) NOT NULL, user_id BINARY(16) NOT NULL, invited_by BINARY(16) NOT NULL, `name` VARCHAR(512) NOT NULL, lastname VARCHAR(512) NOT NULL, phone VARCHAR(512) NULL, email VARCHAR(512) NULL, status INT NOT NULL, CONSTRAINT fk_employee_invitation_business_id__id FOREIGN KEY (business_id) REFERENCES business(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX employee_invitation_business_id ON employee_invitation (business_id);
CREATE INDEX employee_invitation_user_id ON employee_invitation (user_id);
ALTER TABLE employee_invitation ADD CONSTRAINT employee_invitation_business_id_user_id_unique UNIQUE (business_id, user_id);
CREATE TABLE IF NOT EXISTS signing_key (id BINARY(16) PRIMARY KEY, public_key text NOT NULL, private_key text NOT NULL, status INT NOT NULL, created_at TIMESTAMP(6) NOT NULL, retired_at TIMESTAMP(6) NULL);
CREATE INDEX signing_key_status ON signing_key (status);
